SELECT CONCAT('CAT', TO_CHAR(now(), 'YYYYMM'), LPAD(CAST(NEXTVAL('dtmeta.seq_tb_meta_category') AS varchar), 6, '0'))	

INSERT /* SQL_ID: CategoryMapper.insertCategoryAutoKey */
       INTO dtmeta.tb_meta_category
	 ( ctgry_id	
	, up_ctgry_id	
	, ctgry_nm
	, ctgry_rdf_cncpt_nm
	, ctgry_data_sttus_mtcd	
	, ctgry_sort_odrg	
	, ctgry_desc	
	, ctgry_eng_nm	
	, ctgry_eng_desc	
	, ctgry_mappg_cd	
	, cntry_cd	
	, ctgry_type_mtcd	
	, ctgry_regr_id	
	, ctgry_regr_nm	
	, ctgry_reg_dt	
	, ctgry_amdr_id	
	, ctgry_amdr_nm	
	, ctgry_amd_dt			

	 ) VALUES 
	 ( 
	  #{ctgryId}	
	, #{upCtgryId}	
	, #{ctgryNm}
	, #{ctgryRdfCncptNm}
	, #{ctgryDataSttusMtcd}
	, #{ctgrySortOdrg}
	, #{ctgryDesc}	
	, #{ctgryEngNm}	
	, #{ctgryEngDesc}	
	, #{ctgryMappgCd}	
	, #{cntryCd}	
	, #{ctgryTypeMtcd}	
	, #{ctgryRegrId}	
	, #{ctgryRegrNm}	
	, current_timestamp
	, #{ctgryAmdrId}	
	, #{ctgryAmdrNm}	
	, current_timestamp
	)

mapper.update:
		UPDATE /* SQL_ID: CategoryMapper.updateCategory */
               dtmeta.tb_meta_category
		   SET up_ctgry_id					= #{upCtgryId}
             , ctgry_nm						= #{ctgryNm}
             , ctgry_rdf_cncpt_nm			= #{ctgryRdfCncptNm}
             , ctgry_data_sttus_mtcd		= #{ctgryDataSttusMtcd}
             , ctgry_sort_odrg				= #{ctgrySortOdrg}
             , ctgry_desc					= #{ctgryDesc}
             , ctgry_eng_nm					= #{ctgryEngNm}
             , ctgry_eng_desc				= #{ctgryEngDesc}
             , ctgry_mappg_cd				= #{ctgryMappgCd}
             , cntry_cd						= #{cntryCd}
             , ctgry_type_mtcd				= #{ctgryTypeMtcd}
             , ctgry_amdr_id				= #{ctgryAmdrId}
             , ctgry_amdr_nm				= #{ctgryAmdrNm}
             , ctgry_amd_dt					= current_timestamp            
		 WHERE ctgry_id 	    = #{ctgryId}

		UPDATE /* SQL_ID: AgentMapper.updateCategoryStatus */
               dtmeta.tb_meta_category
		   SET medata_set_sttus_mtcd		= #{ctgryDataSttusMtcd}
             , ctgry_amdr_id				= #{ctgryAmdrId}
             , ctgry_amdr_nm				= #{ctgryAmdrNm}
             , ctgry_amd_dt					= current_timestamp            
		 WHERE ctgry_id 	    = #{ctgryId}

mapper.delete:
DELETE /* SQL_ID: CategoryMapper.deleteCategory */
  FROM dtmeta.tb_meta_category
 WHERE ctgry_id = #{ctgryId}

mapper.select:
SELECT EXISTS ( /* SQL_ID: CategoryMapper.selectMetaDataByCategory */
	SELECT 1 
	FROM dtmeta.tb_meta_data
	WHERE medata_val = #{ctgryId}
)

SELECT EXISTS ( /* SQL_ID: CategoryMapper.selectCountryCodeByCntryCd */
	SELECT 1 
	FROM dtmeta.tb_portal_countrycode
	WHERE cntry_cd = #{cntryCd}
)

SELECT EXISTS ( /* SQL_ID: CategoryMapper.selectIsUpperCategory */
	SELECT 1 
	FROM dtmeta.tb_meta_category
	WHERE up_ctgry_id = #{ctgryId}
)

SELECT EXISTS (  /* SQL_ID: CategoryMapper.isCtgryRdfCncptNmExist */
	SELECT 1
	FROM dtmeta.tb_meta_category
	WHERE  ctgry_rdf_cncpt_nm = #{ctgryRdfCncptNm}

		AND ctgry_id  != #{ctgryId}

)
